INSERT INTO projects (slug,name,description,long_description,why_it_exists,type,status,stack,topics,repo_url,homepage,cover_pattern,cover_color,featured,sort_order) VALUES
('headcount','Headcount','A public dashboard that scores Twitch top-200 streams for patterns that view-bots, follow-bots and chat-bots produce.','Headcount tracks every Twitch channel once it reaches the global top 200 and records its viewers, chat and follower total each minute. When a stream ends, twelve detectors rate the evidence and combine into a sus quotient from 0 to 100. A high quotient means the data has patterns bots produce; it does not prove a streamer bought bots. Collection began in October 2026, so early scores are provisional and change often.','A viewer count is easy to inflate and hard to check from outside. Headcount puts each stream’s viewers beside its chatters and follows so anyone can look.',ARRAY['software','media']::text[],'incubating',ARRAY['Go','PostgreSQL','TimescaleDB']::text[],ARRAY['twitch','bots','analytics']::text[],'https://git.subcult.tv/subculture-collective/headcount','https://headcount.subcult.tv','grid','#f2b53a',false,23)
ON CONFLICT (slug) DO NOTHING;
